/* A loopback RDP peer generating test pixels. Never captures a desktop. */
#include <freerdp/freerdp.h>
#include <freerdp/peer.h>
#include <freerdp/settings.h>
#include <freerdp/update.h>
#include <freerdp/input.h>
#include <freerdp/crypto/privatekey.h>
#include <freerdp/crypto/certificate.h>
#include <winpr/ssl.h>
#include <winpr/ntlm.h>
#include <winpr/synch.h>
#include <winpr/sysinfo.h>
#include <winpr/wlog.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <poll.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

static FILE* events;
static int useNLA,resizeMode;
static void note(const char* text){fprintf(events,"%s\n",text);fflush(events);}
#include "rdp_clipboard_server.h"
static BOOL paint(rdpContext* context,int x,int y,int w,int h,int solid){size_t row=(size_t)w*3;BYTE* data=calloc(row*(size_t)h,1);if(!data)return FALSE;for(int j=0;j<h;j++){int top=h-j-1;for(int i=0;i<w;i++){BYTE r=0,g=0,b=0;if(solid){g=255;}else if(top<h/2){if(i<w/2)r=255;else b=255;}else{g=255;if(i>=w/2)r=255;}BYTE* pixel=data+row*(size_t)j+3*(size_t)i;pixel[0]=b;pixel[1]=g;pixel[2]=r;}}BITMAP_DATA rectangle={0};rectangle.destLeft=x;rectangle.destTop=y;rectangle.destRight=x+w-1;rectangle.destBottom=y+h-1;rectangle.width=w;rectangle.height=h;rectangle.bitsPerPixel=24;rectangle.bitmapLength=(UINT32)(row*(size_t)h);rectangle.bitmapDataStream=data;rectangle.compressed=FALSE;BITMAP_UPDATE update={.number=1,.rectangles=&rectangle,.skipCompression=TRUE};BOOL result=context->update->BitmapUpdate(context,&update);free(data);return result;}
static BOOL activated(freerdp_peer* peer){clipboardActivated=1;note("{\"type\":\"activated\"}");if(!fixture_clipboard_start(peer))return FALSE;return paint(peer->context,0,0,64,48,0);}
static BOOL post_connect(freerdp_peer* peer){const char* user=freerdp_settings_get_string(peer->context->settings,FreeRDP_Username);const char* password=freerdp_settings_get_string(peer->context->settings,FreeRDP_Password);if(!useNLA&&(!user||strcmp(user,"testuser")||!password||strcmp(password,"RdpTestPass"))){note("{\"type\":\"loginRejected\"}");return FALSE;}note("{\"type\":\"postconnect\"}");return TRUE;}
static BOOL logon(freerdp_peer* peer,const SEC_WINNT_AUTH_IDENTITY* identity,BOOL automatic){(void)peer;(void)identity;note(automatic?"{\"type\":\"logon\",\"nla\":true}":"{\"type\":\"logon\",\"nla\":false}");return TRUE;}
static BOOL key_event(rdpInput* input,UINT16 flags,UINT8 code){fprintf(events,"{\"type\":\"key\",\"flags\":%u,\"code\":%u}\n",flags,code);fflush(events);if(!(flags&KBD_FLAGS_RELEASE)&&code==0x13&&resizeMode){rdpSettings* settings=input->context->settings;if(!freerdp_settings_set_uint32(settings,FreeRDP_DesktopWidth,resizeMode==2?8192:480)||!freerdp_settings_set_uint32(settings,FreeRDP_DesktopHeight,resizeMode==2?8192:320))return FALSE;return input->context->update->DesktopResize(input->context);}return TRUE;}
static BOOL unicode_event(rdpInput* input,UINT16 flags,UINT16 code){fprintf(events,"{\"type\":\"unicode\",\"flags\":%u,\"code\":%u}\n",flags,code);fflush(events);if(!(flags&KBD_FLAGS_RELEASE))return paint(input->context,80,0,16,16,1);return TRUE;}
static BOOL mouse_event(rdpInput* input,UINT16 flags,UINT16 x,UINT16 y){fprintf(events,"{\"type\":\"mouse\",\"flags\":%u,\"x\":%u,\"y\":%u}\n",flags,x,y);fflush(events);(void)input;return TRUE;}
static BOOL sync_event(rdpInput* input,UINT32 flags){(void)input;(void)flags;return TRUE;}
int main(int argc,char** argv){if(argc!=3)return 2;signal(SIGPIPE,SIG_IGN);useNLA=strcmp(argv[2],"tls")!=0;clipboardMode=!strncmp(argv[2],"clipboard",9)?argv[2]:NULL;if(clipboardMode&&!WTSRegisterWtsApiFunctionTable(FreeRDP_InitWtsApi()))return 2;resizeMode=!strcmp(argv[2],"resize")?1:!strcmp(argv[2],"resize-oversize")?2:0;char path[4096];snprintf(path,sizeof(path),"%s/events.jsonl",argv[1]);events=fopen(path,"w");if(!events)return 2;WLog_SetLogLevel(WLog_GetRoot(),WLOG_ERROR);winpr_InitializeSSL(WINPR_SSL_INIT_DEFAULT);int listener=socket(AF_INET,SOCK_STREAM,0);struct sockaddr_in address={.sin_len=sizeof(address),.sin_family=AF_INET,.sin_addr.s_addr=htonl(INADDR_LOOPBACK),.sin_port=0};if(bind(listener,(struct sockaddr*)&address,sizeof(address))||listen(listener,1))return 2;socklen_t size=sizeof(address);if(getsockname(listener,(struct sockaddr*)&address,&size))return 2;snprintf(path,sizeof(path),"%s/port",argv[1]);FILE* port=fopen(path,"w");if(!port)return 2;fprintf(port,"%u",ntohs(address.sin_port));fclose(port);struct pollfd poller={.fd=listener,.events=POLLIN};if(poll(&poller,1,20000)<=0)return 3;int socket=accept(listener,NULL,NULL);close(listener);if(socket<0)return 2;freerdp_peer* peer=freerdp_peer_new(socket);if(!peer||!freerdp_peer_context_new(peer))return 2;if(clipboardMode){clipboardManager=WTSOpenServerA((LPSTR)peer->context);if(!clipboardManager||clipboardManager==INVALID_HANDLE_VALUE)return 2;}rdpSettings* settings=peer->context->settings;snprintf(path,sizeof(path),"%s/server.key",argv[1]);rdpPrivateKey* key=freerdp_key_new_from_file_enc(path,NULL);snprintf(path,sizeof(path),"%s/server.crt",argv[1]);rdpCertificate* certificate=freerdp_certificate_new_from_file(path);if(!key||!certificate)return 2;BOOL ok=freerdp_settings_set_pointer_len(settings,FreeRDP_RdpServerRsaKey,key,1)&&freerdp_settings_set_pointer_len(settings,FreeRDP_RdpServerCertificate,certificate,1)&&freerdp_settings_set_bool(settings,FreeRDP_RdpSecurity,FALSE)&&freerdp_settings_set_bool(settings,FreeRDP_TlsSecurity,!useNLA)&&freerdp_settings_set_bool(settings,FreeRDP_NlaSecurity,useNLA)&&freerdp_settings_set_bool(settings,FreeRDP_ExtSecurity,FALSE)&&freerdp_settings_set_uint32(settings,FreeRDP_ColorDepth,32)&&freerdp_settings_set_bool(settings,FreeRDP_RemoteFxCodec,FALSE)&&freerdp_settings_set_bool(settings,FreeRDP_NSCodec,FALSE)&&freerdp_settings_set_bool(settings,FreeRDP_SupportGraphicsPipeline,FALSE);if(useNLA){BYTE hash[16];if(!NTOWFv1A("RdpTestPass",11,hash))return 2;snprintf(path,sizeof(path),"%s/sam",argv[1]);FILE* sam=fopen(path,"w");if(!sam)return 2;fprintf(sam,"testuser:::");for(size_t i=0;i<16;i++)fprintf(sam,"%02X",hash[i]);fprintf(sam,":\n");fclose(sam);ok=ok&&freerdp_settings_set_string(settings,FreeRDP_NtlmSamFile,path);}if(!ok)return 2;peer->PostConnect=post_connect;peer->Activate=activated;peer->Logon=logon;peer->context->input->KeyboardEvent=key_event;peer->context->input->UnicodeKeyboardEvent=unicode_event;peer->context->input->MouseEvent=mouse_event;peer->context->input->SynchronizeEvent=sync_event;if(peer->Initialize(peer)){UINT64 deadline=GetTickCount64()+20000;while(GetTickCount64()<deadline){HANDLE handles[32];DWORD count=peer->GetEventHandles(peer,handles,31);if(clipboardManager)handles[count++]=WTSVirtualChannelManagerGetEventHandle(clipboardManager);if(!count||WaitForMultipleObjects(count,handles,FALSE,100)==WAIT_FAILED||!peer->CheckFileDescriptor(peer)||(clipboardManager&&!WTSVirtualChannelManagerCheckFileDescriptor(clipboardManager))||!fixture_clipboard_start(peer))break;}peer->Disconnect(peer);}if(clipboardServer){clipboardServer->Stop(clipboardServer);cliprdr_server_context_free(clipboardServer);}if(clipboardManager)WTSCloseServer(clipboardManager);note("{\"type\":\"closed\"}");freerdp_peer_context_free(peer);freerdp_peer_free(peer);fclose(events);return 0;}
